import { hostedControlPlaneFetch } from "./hosted-fetch.js";
import { newSessionId } from "./ids.js";
const CONTINUATION_SESSION_PATH = "/internal/agentsdk/sessions/continuation";
const PLATFORM_SESSION_ID = /^ses_[0-9a-f]{24}$/;
export const localSessionIds = {
    async allocate() {
        return newSessionId();
    },
};
export function sessionIdSourceForGuest(input, hosted) {
    if (input.noControlPlane && input.architecture === "v2") {
        return createCursorHostedContinuationSessionIds(hosted);
    }
    return localSessionIds;
}
export function createCursorHostedContinuationSessionIds(options = {}) {
    return {
        async allocate(input) {
            if (!input.continuationKey.startsWith("cont:")) {
                return newSessionId();
            }
            const response = await hostedControlPlaneFetch(options, "POST", CONTINUATION_SESSION_PATH, {
                channelId: input.channelId,
                continuationKey: input.continuationKey,
            });
            if (!response.ok) {
                const text = await response.text();
                throw new Error(`continuation session allocate failed: HTTP ${response.status} ${text}`);
            }
            const parsed = await response.json();
            if (!isPlatformSessionId(parsed)) {
                throw new Error("continuation session allocate returned an invalid session id");
            }
            return parsed.publicId;
        },
    };
}
function isPlatformSessionId(value) {
    if (value === null || typeof value !== "object" || !("publicId" in value)) {
        return false;
    }
    return typeof value.publicId === "string" && PLATFORM_SESSION_ID.test(value.publicId);
}
